sys_ws_operation.operation_script:
// sn-scriptsync - Received from background script tab via SN Utils.

// CREATE CARD - POST METHOD
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
   // Parse JSON payload
    var payload = request.body.data;

    if (!payload) {
        gs.error("No payload in request");
        response.setStatus(400);
        return;
    }

    var trelloCardId = payload.u_trello_card_id;

    if (!trelloCardId) {
        gs.error("Missing Trello card ID in payload");
        response.setStatus(400);
        return;
    }

    // Check if card exist - u_trello_card_id is external ID
    var gr = new GlideRecord('vtb_card');  
    gr.addQuery('u_trello_card_id', trelloCardId);
    gr.query();

    if (gr.next()) {
        // Card exist so return info and don't create a card
        gs.info("Card already exist: " + gr.getUniqueValue());
        var existingData = {
            sys_id: gr.getUniqueValue(),
            message: "Card with Trello ID '" + trelloCardId + "' already exist",
            short_description: gr.short_description
        };
        response.setBody(existingData);
        response.setStatus(409);
        return;
    }

    // Create new private task

    var newTask = new GlideRecord('vtb_task');
    newTask.initialize();
    newTask.short_description = payload.short_description || 'Missing description';
    newTask.description = payload.u_card_content || '';

    var newTaskID = newTask.insert();

    // Create new card, assign to private task
    var newCard = new GlideRecord('vtb_card');
    newCard.initialize();

    newCard.task = newTaskID;
    newCard.board = '91428defc3ba72101cae1933e40131c3'; //baby raccon board
    newCard.lane = getListID(payload.u_list_name);
    newCard.u_source = payload.u_source || '';
    newCard.u_trello_card_id = payload.u_trello_card_id;

    var newCardSysId = newCard.insert();

    if (newCardSysId) {
        gs.info("Created new card: " + newCardSysId);
        var result = {
            sys_id: newCardSysId,
            message: "New card created succesfully",
            trello_card_id: trelloCardId
        };
        response.setBody(result);
        response.setStatus(201);
    } else {
        gs.error("Error while creating the card");
        response.setStatus(500);
    }

    // Get Trello list name and return SYS_ID from corresponding list in Snow
    function getListID(listName){

        // Default lane is TODO / Do zrobienia
        var DEFAULT_LANE = '1d424523c3fa72101cae1933e4013137';

        var grList = new GlideRecord('vtb_lane');
        grList.addQuery('name', listName);
        grList.query();

        return grList.next() ? grList.sys_id : DEFAULT_LANE;

    }

})(request, response);
